class Solution {
    public int maxProduct(int[] nums) {
        int max = nums[0];
        int min = nums[0];
        int res = nums[0];
        for(int i = 1;i<nums.length;i++){
            int premax = max;
            int premin = min;
            max = Math.max(nums[i],Math.max(premax*nums[i],premin*nums[i]));
            min = Math.min(nums[i],Math.min(premax*nums[i],premin*nums[i]));
            res = Math.max(res,max);
        }
        return res;
    }
}
